class Solution {
  public int[][] candyCrush(int[][] board) {
    int m = board.length, n = board[0].length;
    boolean changed = true;
    while (changed) {
      changed = false;
      // mark (negate) every run of three or more, horizontally and vertically
      for (int i = 0; i < m; i++)
        for (int j = 0; j + 2 < n; j++) {
          int v = Math.abs(board[i][j]);
          if (v != 0 && Math.abs(board[i][j + 1]) == v && Math.abs(board[i][j + 2]) == v) {
            board[i][j] = board[i][j + 1] = board[i][j + 2] = -v;
            changed = true;
          }
        }
      for (int j = 0; j < n; j++)
        for (int i = 0; i + 2 < m; i++) {
          int v = Math.abs(board[i][j]);
          if (v != 0 && Math.abs(board[i + 1][j]) == v && Math.abs(board[i + 2][j]) == v) {
            board[i][j] = board[i + 1][j] = board[i + 2][j] = -v;
            changed = true;
          }
        }
      // gravity: keep the positive candies, dropping them to the bottom
      for (int j = 0; j < n; j++) {
        int write = m - 1;
        for (int i = m - 1; i >= 0; i--) if (board[i][j] > 0) board[write--][j] = board[i][j];
        while (write >= 0) board[write--][j] = 0;
      }
    }
    return board;
  }
}
